<template>
  <div class="page-stack">
    <div class="back-row"><el-button link @click="$router.push('/results')"><el-icon><ArrowLeft/></el-icon> 返回结果中心</el-button><div class="top-actions"><el-button v-if="!['question','batch'].includes(route.params.type)" @click="openArtifacts" :loading="openingFolder"><el-icon><FolderOpened/></el-icon> {{route.params.type==='schematic'?'打开原理图项目文件夹':'打开评测产物文件夹'}}</el-button><el-button @click="load(false)" :loading="loading"><el-icon><Refresh/></el-icon> 刷新</el-button></div></div>
    <el-skeleton v-if="loading&&!detail" :rows="8" animated/>
    <template v-else-if="detail">
      <section class="hero compact"><div><span class="eyebrow">{{typeLabel}} RESULT</span><h1>{{title}}</h1><p>评测 ID {{route.params.id}} · {{formatTime(detail.created_at)}} · {{statusText(detail.status||'completed')}}</p></div><el-tag size="large" :type="statusType(detail.status)">{{statusText(detail.status||'completed')}}</el-tag></section>
      <el-alert v-if="detail.status==='failed'&&failure" class="failure-alert" type="error" show-icon :closable="false" :title="failureTitle(failure)" :description="`${failureDescription(failure)} 本页分数仅用于故障诊断，不参与排名。`"/>

      <el-card v-if="isLive" shadow="never" class="panel live-panel">
        <template #header><div class="section-head"><div><b><i v-if="isLive" class="live-dot"/>实时运行过程</b><span>按发生顺序显示评测阶段、Agent/模型回复和工具交互</span></div><el-tag :type="isLive?'warning':'success'">{{isLive?'实时更新':'运行已结束'}}</el-tag></div></template>
        <el-progress v-if="isLive" :percentage="Number(detail.progress||0)" :stroke-width="8"/>
        <div v-if="!autoFollowEvents" class="follow-controls"><el-button size="small" type="primary" plain @click="resumeEventFollow">继续跟随最新内容</el-button></div>
        <div class="event-stream" ref="eventStream" @scroll.passive="onEventScroll">
          <article v-for="event in liveEvents" :key="event.sequence" :class="`event-${event.kind}`">
            <header><b>{{eventKind(event)}}</b><span>{{formatTime(event.timestamp)}}</span><em v-if="event.tool">{{event.tool}}</em></header>
            <pre>{{event.content}}</pre>
          </article>
          <el-empty v-if="!liveEvents.length" description="任务正在准备，等待第一条运行事件"/>
        </div>
      </el-card>

      <el-card v-if="!['question','batch'].includes(route.params.type) && !isLive" shadow="never" class="panel interactions-panel">
        <template #header><div class="section-head"><div><b>模型交互记录</b><span>先查看逐次调用列表，点击任意记录展开提示词、历史、模型输出和工具详情</span></div><el-tag effect="plain">{{interactionTotal}} 条匹配记录</el-tag></div></template>
        <div class="interaction-controls">
          <el-segmented v-model="interactionScope" :options="interactionScopeOptions" @change="changeInteractionScope"/>
          <el-select v-if="interactionScope==='subagent'" v-model="interactionSubagent" clearable placeholder="选择一个 Subagent" @change="changeInteractionSubagent"><el-option v-for="item in interactionSubagents" :key="item.name" :label="`${item.name}（${item.interaction_count} 次）`" :value="item.name"/></el-select>
          <el-input v-model="interactionSearch" clearable placeholder="搜索提示词、模型输出、工具名或请求 ID" @keyup.enter="searchInteractions"><template #append><el-button @click="searchInteractions">搜索</el-button></template></el-input>
        </div>
        <div class="interaction-summary"><div><span>当前范围开始时间</span><b>{{formatTime(interactionFilteredSummary.started_at)}}</b></div><div><span>当前范围总用时</span><b>{{durationText(interactionFilteredSummary.duration_ms)}}</b></div><div><span>当前范围 Token</span><b>{{number(interactionFilteredSummary.total_tokens)}}</b></div><div><span>工具调用 / 启动子任务</span><b>{{number(interactionFilteredSummary.tool_call_count)}} / {{number(interactionFilteredSummary.subagent_start_count)}}</b></div></div>
        <div v-if="interactionSubagents.length" class="subagent-overview"><div class="subagent-overview-title"><b>Subagent 独立记录</b><span>点击子任务即可只查看它自己的模型请求与输出</span></div><div class="subagent-list"><button v-for="item in interactionSubagents" :key="item.name" type="button" :class="{active:interactionScope==='subagent'&&interactionSubagent===item.name}" @click="selectSubagent(item.name)"><b>{{item.name}}</b><span>{{item.interaction_count}} 次调用 · {{number(item.total_tokens)}} tokens · {{durationText(item.duration_ms)}}</span></button></div></div>
        <el-collapse v-if="interactions.length" v-model="expandedInteractions" class="interaction-log-list">
          <el-collapse-item v-for="(item,index) in interactions" :key="interactionKey(item,index)" :name="interactionKey(item,index)">
            <template #title><div class="interaction-log-row"><span class="turn-index">{{item.turn_index||((interactionPage-1)*interactionPageSize+index+1)}}</span><div class="interaction-log-main"><div><b>{{item.model_group||item.model||'未知模型'}}</b><el-tag size="small" effect="plain" :type="item.interaction_scope==='subagent'?'warning':'primary'">{{actorLabel(item)}}</el-tag><el-tag size="small" :type="item.status==='success'?'success':'danger'">{{interactionStatus(item.status)}}</el-tag></div><p>{{interactionPreview(item)}}</p></div><div class="interaction-log-meta"><span>{{formatTime(item.start_time)}}</span><span>{{durationText(item.request_duration_ms)}} · {{number(item.total_tokens)}} tokens · 工具 {{number(item.tool_call_count)}}</span></div></div></template>
            <div v-if="isInteractionExpanded(item,index)" class="interaction-detail">
              <div class="interaction-detail-meta"><span>Request ID：{{item.request_id||'未记录'}}</span><span>Session ID：{{item.session_id||'未记录'}}</span><span>输入 {{number(item.prompt_tokens)}} / 输出 {{number(item.completion_tokens)}} tokens</span></div>
              <section class="message-section user-prompt"><header><b>用户提示词</b><span>{{currentUserMessages(item).length}} 条</span></header><div v-if="currentUserMessages(item).length" class="message-stack"><article v-for="(message,mIndex) in currentUserMessages(item)" :key="`user-${mIndex}`"><pre>{{contentText(message.content)}}</pre></article></div><el-empty v-else description="本次请求没有单独记录用户提示词" :image-size="48"/></section>
              <section class="message-section system-prompt"><header><b>系统提示词</b><span>{{systemPromptMessages(item).length}} 条</span></header><div v-if="systemPromptMessages(item).length" class="message-stack"><article v-for="(message,mIndex) in systemPromptMessages(item)" :key="`system-${mIndex}`"><pre>{{contentText(message.content)}}</pre></article></div><el-empty v-else description="本次请求没有记录系统提示词" :image-size="48"/></section>
              <section class="message-section model-output"><header><b>模型输出</b><span>{{responseMessages(item).length}} 条</span></header><div v-if="responseMessages(item).length" class="message-stack"><article v-for="(message,mIndex) in responseMessages(item)" :key="`output-${mIndex}`"><pre>{{contentText(message.content)}}</pre></article></div><el-empty v-else description="模型没有返回文本内容" :image-size="48"/></section>
              <section class="message-section history"><header><b>历史消息</b><span>{{historyMessages(item).length}} 条</span></header><div v-if="historyMessages(item).length" class="message-stack"><article v-for="(message,mIndex) in historyMessages(item)" :key="`history-${mIndex}`"><strong>{{roleLabel(message.role)}}</strong><pre>{{contentText(message.content)}}</pre></article></div><el-empty v-else description="这是会话首轮，没有历史消息" :image-size="48"/></section>
              <section v-if="responseToolCalls(item).length" class="message-section tools"><header><b>本轮工具调用</b><span>{{responseToolCalls(item).length}} 次</span></header><div class="message-stack"><article v-for="(tool,tIndex) in responseToolCalls(item)" :key="tool.id||`${tool.name}-${tIndex}`"><strong>{{tool.name}}</strong><pre>{{readable(tool.arguments)}}</pre></article></div></section>
              <details class="raw-interaction"><summary>查看 LiteLLM 原始请求与响应</summary><div class="interaction-body"><article><span>原始请求</span><pre>{{pretty(item.proxy_server_request||item.messages||{})}}</pre></article><article><span>原始响应</span><pre>{{pretty(item.response||{})}}</pre></article></div></details>
            </div>
          </el-collapse-item>
        </el-collapse>
        <el-empty v-else description="本次运行没有匹配的模型交互；请检查数据库轨迹状态或搜索条件"/>
        <el-pagination v-if="interactionTotal>interactionPageSize" class="interaction-pagination" background layout="total, prev, pager, next, sizes" :total="interactionTotal" v-model:current-page="interactionPage" v-model:page-size="interactionPageSize" :page-sizes="[10,20,50,100]" @current-change="changeInteractionPage" @size-change="changeInteractionPageSize"/>
      </el-card>

      <template v-if="route.params.type==='batch'">
        <div class="metric-grid"><div><span>评测组合</span><b>{{detail.total_jobs||0}}</b></div><div><span>已结束</span><b>{{detail.completed_jobs||0}}</b></div><div><span>最高得分</span><b>{{score(detail.best?.overall_score)}}</b></div><div><span>最佳组合</span><b class="compact-value">{{detail.best?`${detail.best.agent} × ${detail.best.model}`:'—'}}</b></div></div>
        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>Agent × 模型对比报告</b><span>按综合得分排序，可下钻查看每个组合的完整轨迹与证据</span></div><el-tag effect="plain">{{detail.skills?.join('、')}}</el-tag></div></template>
          <el-table :data="batchRows" row-key="job_id"><el-table-column label="排名" width="76"><template #default="{row}"><span class="rank" :class="{top:row.rank===1}">{{row.rank||'—'}}</span></template></el-table-column><el-table-column prop="agent" label="Agent" width="120"/><el-table-column prop="model" label="模型" min-width="210"/><el-table-column label="综合" width="90"><template #default="{row}"><b>{{score(row.overall_score)}}</b></template></el-table-column><el-table-column label="结果" width="80"><template #default="{row}">{{score(row.result_score)}}</template></el-table-column><el-table-column label="过程" width="80"><template #default="{row}">{{score(row.process_score)}}</template></el-table-column><el-table-column label="Skill" width="80"><template #default="{row}">{{score(row.skill_quality_score)}}</template></el-table-column><el-table-column label="耗时" width="100"><template #default="{row}">{{durationText(row.duration_ms)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusText(row.status)}}</el-tag></template></el-table-column><el-table-column label="失败原因" min-width="230"><template #default="{row}"><div v-if="row.status==='failed'" class="failure-cell"><b>{{failureTitle(row.failure)}}</b><small>{{failureShortDetail(row.failure,row.error)}}</small></div><span v-else>—</span></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/results/${detail.evaluation_type||'skill'}/${row.job_id}`)">查看详情</el-button></template></el-table-column></el-table>
        </el-card>
        <el-card shadow="never" class="panel"><template #header><b>对比结论</b></template><div class="comparison-conclusion" v-if="detail.best"><el-icon><Trophy/></el-icon><div><b>{{detail.best.agent}} × {{detail.best.model}} 当前排名第一</b><p>综合得分 {{score(detail.best.overall_score)}}，结果质量 {{score(detail.best.result_score)}}，过程质量 {{score(detail.best.process_score)}}。排名基于同一任务、同一 Skill 与相同运行参数下的结果。</p></div></div><el-empty v-else :description="detail.status === 'completed' ? '所有组合均失败，无有效排名' : '组合仍在评测中，完成后生成对比结论'"/></el-card>
      </template>
      <template v-else-if="route.params.type==='question'">
        <div class="metric-grid"><div><span>执行结果</span><b>{{questionMetrics.count}}</b></div><div><span>通过率</span><b>{{percent(questionMetrics.score)}}</b></div><div><span>错误率</span><b>{{percent(questionMetrics.error_rate)}}</b></div><div><span>Token</span><b>{{number(questionMetrics.tokens)}}</b></div></div>
        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>逐题评测过程</b><span>查看题目、响应、评分与错误证据</span></div><el-tag effect="plain">{{results.length}} 条</el-tag></div></template>
          <el-collapse class="case-list">
            <el-collapse-item v-for="(row,index) in results" :key="row.id||`${row.item_key}-${index}`" :name="index">
              <template #title><div class="case-title"><span class="case-index">{{index+1}}</span><b>{{row.item_key||row.benchmark_item_key||`题目 ${index+1}`}}</b><el-tag size="small" :type="row.status==='error'?'danger':row.passed?'success':'warning'">{{row.status==='error'?'执行错误':row.passed?'通过':'未通过'}}</el-tag><span class="case-meta">{{row.provider_name}} · {{durationText(row.wall_duration_ms||row.duration_ms||row.latency_ms)}}</span></div></template>
              <div class="case-body question-answer-grid">
                <article><span>题目</span><p>{{row.prompt||'未记录题目内容'}}</p></article>
                <article class="answer"><span>模型响应</span><p>{{row.response_text||row.output||row.response||'模型未返回内容'}}</p></article>
                <article><span>正确答案</span><p>{{readable(row.expected)}}</p></article>
                <article><span>模型得分</span><p>{{questionScore(row)}}；判定：{{row.status==='error'?'执行错误':row.passed?'通过':'未通过'}}</p></article>
                <article v-if="row.error" class="error-box"><span>执行错误</span><p>{{row.error}}</p></article>
                <div class="case-stats"><span>输入 {{number(row.input_tokens)}} tokens</span><span>输出 {{number(row.output_tokens)}} tokens</span><span>重复轮次 {{row.repeat??1}}</span></div>
              </div>
            </el-collapse-item>
          </el-collapse>
        </el-card>
        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>模型表现汇总</b><span>通过率、时延与成本覆盖</span></div></div></template>
          <el-table :data="summaryRows"><el-table-column prop="provider_name" label="模型 / Agent" min-width="180"/><el-table-column prop="benchmark_name" label="题库" min-width="180"/><el-table-column label="通过率" width="100"><template #default="{row}">{{percent(row.score)}}</template></el-table-column><el-table-column prop="completed" label="完成" width="80"/><el-table-column label="P50 时延" width="110"><template #default="{row}">{{durationText(row.p50_latency_ms)}}</template></el-table-column><el-table-column label="P95 时延" width="110"><template #default="{row}">{{durationText(row.p95_latency_ms)}}</template></el-table-column><el-table-column label="证据量" width="110"><template #default="{row}">{{evidenceLabel(row.sample_size_status)}}</template></el-table-column></el-table>
          <el-empty v-if="!summaryRows.length" description="暂无汇总数据"/>
        </el-card>
        <el-card v-if="pairedRows.length" shadow="never" class="panel"><template #header><b>成对对比</b></template><el-table :data="pairedRows"><el-table-column label="对比对象" min-width="260"><template #default="{row}">{{row.left_name}} vs {{row.right_name}}</template></el-table-column><el-table-column prop="left_wins" label="左胜" width="80"/><el-table-column prop="right_wins" label="右胜" width="80"/><el-table-column prop="ties" label="持平" width="80"/><el-table-column label="显著性" width="140"><template #default="{row}"><el-tag :type="row.significant_005?'success':'info'">{{row.significant_005?'显著':'暂无显著差异'}}</el-tag></template></el-table-column></el-table></el-card>
      </template>

      <template v-else>
        <div class="metric-grid"><div><span>总体得分</span><b>{{score(detail.scores?.overall_score??detail.scoring?.overall_score)}}</b></div><div><span>结果质量</span><b>{{score(detail.scores?.result_dimension_score??dimensions.result?.score)}}</b></div><div><span>过程质量</span><b>{{score(detail.scores?.process_dimension_score??dimensions.process?.score)}}</b></div><div><span>Skill 质量</span><b>{{score(detail.scores?.skill_quality_dimension_score??detail.skill_quality?.score)}}</b></div></div>

        <el-card shadow="never" class="panel overview-card">
          <div class="run-overview"><div><span>Agent</span><b>{{detail.agent||'-'}}</b></div><div><span>模型</span><b>{{detail.provider_model||detail.model||'-'}}</b></div><div><span>评测 Skill</span><b>{{skillNames.join('、')||'-'}}</b></div><div><span>总耗时</span><b>{{durationText(detail.scores?.total_duration_ms)}}</b></div><div><span>总 Token</span><b>{{number(detail.scores?.total_tokens)}}</b></div><div><span>迭代次数</span><b>{{detail.iterations||1}}</b></div></div>
        </el-card>
        <el-alert v-if="detail.evaluation_type==='schematic'&&skillUsage.status" :type="skillUsage.all_selected_skills_read?'success':'warning'" show-icon :closable="false" :title="skillUsage.all_selected_skills_read?'已验证所有选定 Skill 的显式读取':'未验证全部选定 Skill 的显式读取'" :description="`已读取：${skillUsage.observed_skills?.join('、')||'无'}；缺少证据：${skillUsage.missing_skills?.join('、')||'无'}。判定依据为数据库轨迹中的 SKILL.md 读取工具调用。`"/>

        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>评测过程与轨迹分析</b><span>从任务执行、工具调用和模型轨迹中提取</span></div><el-tag :type="traceStatus.type" effect="plain">{{traceStatus.label}}</el-tag></div></template>
          <div class="trajectory-grid">
            <div><span>工具调用</span><b>{{process.tool_calls??0}}</b><small>完成率 {{percent(process.tool_completion_rate)}}</small></div>
            <div><span>子 Agent 调用</span><b>{{process.subagent_calls??0}}</b><small>{{process.subagent_detection==='best_effort_tool_name_heuristic'?'启发式识别':'运行时记录'}}</small></div>
            <div><span>模型调用</span><b>{{process.model_call_count??'—'}}</b><small>成功率 {{percent(process.model_call_success_rate)}}</small></div>
            <div><span>错误事件</span><b>{{process.error_event_count??0}}</b><small>工具失败 {{process.tool_failures??0}}</small></div>
          </div>
          <el-timeline class="run-timeline">
            <el-timeline-item v-for="(item,index) in caseRows" :key="`${item.case_id}-${index}`" :type="caseType(item.status)" :timestamp="durationText(item.duration_ms)" placement="top">
              <div class="timeline-card"><div class="timeline-title"><b>{{item.title||item.case_id||`用例 ${index+1}`}}</b><el-tag size="small" :type="caseType(item.status)">{{caseStatus(item.status)}}</el-tag></div><p>{{item.prompt||'未记录任务输入'}}</p><div class="case-stats"><span>{{item.turns||0}} 轮</span><span>{{number(item.input_tokens)}} 输入 tokens</span><span>{{number(item.output_tokens)}} 输出 tokens</span><span>{{item.configuration==='without_skill'?'无 Skill 基线':'使用 Skill'}}</span></div></div>
            </el-timeline-item>
          </el-timeline>
          <el-empty v-if="!caseRows.length" description="本次运行未生成逐用例轨迹"/>
        </el-card>

        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>结果与评分证据</b><span>逐用例查看输入、最终输出和判分依据</span></div></div></template>
          <el-collapse class="case-list" :model-value="caseRows.length===1?[0]:[]">
            <el-collapse-item v-for="(item,index) in caseRows" :key="`${item.case_id}-result-${index}`" :name="index">
              <template #title><div class="case-title"><span class="case-index">{{index+1}}</span><b>{{item.title||item.case_id}}</b><el-tag size="small" :type="caseType(item.status)">{{caseStatus(item.status)}}</el-tag><span class="case-meta">得分 {{caseScore(item)}} · {{durationText(item.duration_ms)}}</span></div></template>
              <div class="case-body"><article><span>任务输入</span><p>{{item.prompt||'—'}}</p></article><article class="answer"><span>Agent 最终输出</span><p>{{item.response||'未记录最终输出'}}</p></article><article v-if="item.error" class="error-box"><span>执行错误</span><p>{{item.error}}</p></article><article><span>评分结论</span><p>{{gradingText(item.grading)}}</p></article></div>
            </el-collapse-item>
          </el-collapse>
        </el-card>

        <el-card v-if="judge.status" shadow="never" class="panel">
          <template #header><div class="section-head"><div><b>LLM Judge</b><span>{{judge.model||judge.profile||'未记录 Judge 模型'}}</span></div><el-tag :type="judgeStatus.type">{{judgeStatus.label}}</el-tag></div></template>
          <el-alert v-if="judge.status==='unavailable'" type="warning" show-icon :closable="false" :title="failureTitle(judge.failure,'Judge 当前不可用')" :description="failureDescription(judge.failure,judge.error||'综合评分已退回规则评分')"/>
          <el-alert v-else-if="judge.status==='skipped_due_to_execution_failure'" type="info" show-icon :closable="false" title="Agent 执行失败，已跳过 LLM Judge" description="无有效最终结果可供 Judge 评分，系统没有继续请求模型额度。综合分仅保留规则诊断结果。"/>
          <el-descriptions v-else-if="judge.status==='completed'" :column="3" border>
            <el-descriptions-item label="Profile">{{judge.profile||'—'}}</el-descriptions-item><el-descriptions-item label="模型">{{judge.model||'—'}}</el-descriptions-item><el-descriptions-item label="Token">{{number(judge.usage?.total_tokens)}}</el-descriptions-item>
          </el-descriptions>
          <el-table v-if="judgeRows.length" :data="judgeRows" style="margin-top:14px"><el-table-column prop="name" label="维度" width="130"/><el-table-column label="分数" width="90"><template #default="{row}"><b>{{score(row.score)}}</b></template></el-table-column><el-table-column label="置信度" width="100"><template #default="{row}">{{percent(row.confidence)}}</template></el-table-column><el-table-column prop="reason" label="Judge 理由" min-width="260"/></el-table>
          <p v-if="judge.summary" class="judge-summary">{{judge.summary}}</p>
        </el-card>

        <el-card shadow="never" class="panel"><template #header><div class="section-head"><div><b>Skill 质量</b><span>{{detail.skill_quality?.method||'结构化质量检查'}}</span></div><el-progress type="circle" :width="54" :stroke-width="6" :percentage="Number(detail.skill_quality?.score||0)"/></div></template>
          <div class="quality-list"><div v-for="item in detail.skill_quality?.details||[]" :key="item.check" :class="{passed:item.passed}"><el-icon><CircleCheckFilled v-if="item.passed"/><CircleCloseFilled v-else/></el-icon><span><b>{{qualityLabel(item.check)}}</b><small>{{qualityDescription(item)}}</small></span><em>+{{item.passed?item.weight:0}} / {{item.weight}}</em></div></div>
          <el-empty v-if="!detail.skill_quality?.details?.length" description="本次报告没有 Skill 质量检查数据"/>
        </el-card>
      </template>
    </template>
    <el-result v-else icon="error" title="无法读取评测结果" :sub-title="error"/>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import { fetchBatch, fetchExperiment, fetchExperimentComparison, fetchExperimentResults, fetchJob, fetchRun, fetchRunInteractions, openRunFolder } from '../api'

const route=useRoute(),loading=ref(false),detail=ref(null),results=ref([]),comparison=ref({}),error=ref(''),eventStream=ref(null),interactions=ref([]),interactionsLoaded=ref(false),openingFolder=ref(false),autoFollowEvents=ref(true),interactionPage=ref(1),interactionPageSize=ref(20),interactionSearch=ref(''),interactionTotal=ref(0),interactionFilteredSummary=ref({}),interactionSubagents=ref([]),interactionScope=ref('all'),interactionSubagent=ref(''),interactionScopeCounts=ref({all:0,main_agent:0,subagent:0}),expandedInteractions=ref([])
let refreshTimer
const typeLabel=computed(()=>({question:'题库评测',schematic:'原理图生成评测',skill:'技能评测',batch:'批量对比评测'}[route.params.type]||'综合评测'))
const title=computed(()=>{const source=String(detail.value?.name||detail.value?.task_name||'').trim();if(/[\u3400-\u9fff]/.test(source))return source;const actor=detail.value?.agent?`${detail.value.agent} `:'';return{question:`${actor}题库能力评测`,schematic:`${actor}原理图生成评测`,skill:`${actor}技能评测`,batch:'多智能体与模型批量对比评测'}[route.params.type]||`${actor}综合评测`})
const batchRows=computed(()=>[...(detail.value?.results||[])].sort((a,b)=>(a.rank||999)-(b.rank||999)))
const summaryRows=computed(()=>Array.isArray(comparison.value?.summary)?comparison.value.summary:[])
const pairedRows=computed(()=>Array.isArray(comparison.value?.paired)?comparison.value.paired:[])
const questionMetrics=computed(()=>{const x=summaryRows.value.reduce((acc,row)=>({count:acc.count+Number(row.completed||0),passed:acc.passed+Number(row.passed||0),errors:acc.errors+Number(row.error_rate||0)*Number(row.completed||0),tokens:acc.tokens+Number(row.tokens||0)}),{count:0,passed:0,errors:0,tokens:0});return{...x,score:x.count?x.passed/x.count:0,error_rate:x.count?x.errors/x.count:0}})
const dimensions=computed(()=>detail.value?.scoring?.dimensions||{})
const process=computed(()=>detail.value?.process_metrics||{})
const skillUsage=computed(()=>detail.value?.skill_usage||{})
const failure=computed(()=>detail.value?.failure||null)
const judge=computed(()=>detail.value?.scoring?.llm_judge||{})
const judgeRows=computed(()=>Object.entries(judge.value.dimensions||{}).map(([name,value])=>({name:({result:'结果',process:'过程',skill_quality:'Skill 质量'}[name]||name),...value})))
const judgeStatus=computed(()=>({completed:{label:'已完成',type:'success'},disabled:{label:'已关闭',type:'info'},disabled_by_request:{label:'已关闭',type:'info'},skipped_due_to_execution_failure:{label:'因执行失败跳过',type:'info'},unavailable:{label:'不可用',type:'warning'}}[judge.value.status]||{label:judge.value.status||'未知',type:'info'}))
const skillNames=computed(()=>detail.value?.skills||[String(detail.value?.skill||'').split(/[\\/]/).filter(Boolean).pop()].filter(Boolean))
const caseRows=computed(()=>{const rows=[];for(const run of detail.value?.results||[])for(const item of run.case_results||[])rows.push(item);return rows})
const traceStatus=computed(()=>{const trace=detail.value?.database_trace||{};if(trace.status==='ok')return{label:'精确轨迹已关联',type:'success'};if(trace.status==='disabled')return{label:'数据库轨迹未启用',type:'info'};return{label:'基于运行报告分析',type:'warning'}})
const isLive=computed(()=>['queued','running','cancelling'].includes(detail.value?.status))
const liveEvents=computed(()=>detail.value?.events||[])
const interactionScopeOptions=computed(()=>[
  {label:`全部 ${interactionScopeCounts.value.all||0}`,value:'all'},
  {label:`主 Agent ${interactionScopeCounts.value.main_agent||0}`,value:'main_agent'},
  {label:`Subagent ${interactionScopeCounts.value.subagent||0}`,value:'subagent'},
])

async function load(silent=false){if(!silent)loading.value=true;error.value='';try{if(route.params.type==='question'){[detail.value,results.value,comparison.value]=await Promise.all([fetchExperiment(route.params.id),fetchExperimentResults(route.params.id),fetchExperimentComparison(route.params.id)])}else if(route.params.type==='batch')detail.value=await fetchBatch(route.params.id);else{let job=null;try{job=await fetchJob(route.params.id)}catch{}if(job)detail.value=job.result?{...job.result,status:job.status,progress:job.progress,events:job.events||[],created_at:job.created_at}:job;else detail.value=await fetchRun(route.params.id);if(!['queued','running','cancelling'].includes(detail.value?.status)&&!interactionsLoaded.value)await loadInteractions()}clearTimeout(refreshTimer);if(['queued','running','cancelling'].includes(detail.value?.status))refreshTimer=setTimeout(()=>load(true),800);await nextTick();if(autoFollowEvents.value&&eventStream.value)eventStream.value.scrollTop=eventStream.value.scrollHeight}catch(e){detail.value=null;error.value=e.response?.data?.detail||e.message;if(!silent)ElMessage.error(error.value)}finally{loading.value=false}}
function onEventScroll(){const el=eventStream.value;if(!el)return;autoFollowEvents.value=el.scrollHeight-el.scrollTop-el.clientHeight<=40}
async function resumeEventFollow(){autoFollowEvents.value=true;await nextTick();if(eventStream.value)eventStream.value.scrollTop=eventStream.value.scrollHeight}
async function loadInteractions(){try{const response=await fetchRunInteractions(route.params.id,{page:interactionPage.value,page_size:interactionPageSize.value,search:interactionSearch.value.trim()||undefined,scope:interactionScope.value,subagent:interactionScope.value==='subagent'?(interactionSubagent.value||undefined):undefined});interactions.value=response.items||[];interactionTotal.value=Number(response.total||0);interactionFilteredSummary.value=response.filtered_summary||response.summary||{};interactionSubagents.value=response.subagents||[];interactionScopeCounts.value=response.scope_counts||{all:interactionTotal.value,main_agent:interactionTotal.value,subagent:0};expandedInteractions.value=[]}catch{interactions.value=[];interactionTotal.value=0;interactionFilteredSummary.value={};interactionSubagents.value=[]}finally{interactionsLoaded.value=true}}
async function searchInteractions(){interactionPage.value=1;await loadInteractions()}
async function changeInteractionScope(){interactionPage.value=1;if(interactionScope.value!=='subagent')interactionSubagent.value='';await loadInteractions()}
async function changeInteractionSubagent(){interactionPage.value=1;await loadInteractions()}
async function selectSubagent(name){interactionScope.value='subagent';interactionSubagent.value=name;interactionPage.value=1;await loadInteractions()}
async function changeInteractionPage(){expandedInteractions.value=[];await loadInteractions()}
async function changeInteractionPageSize(){interactionPage.value=1;expandedInteractions.value=[];await loadInteractions()}
async function openArtifacts(){openingFolder.value=true;try{const result=await openRunFolder(route.params.id);ElMessage.success(`已打开：${result.path}`)}catch(e){ElMessage.error(e.response?.data?.detail||e.message)}finally{openingFolder.value=false}}
const eventKind=event=>({phase:'评测阶段',stdout:'运行输出',stderr:'错误输出',user:'用户输入',assistant:'Agent 回复',model_request:'模型请求',model_response:'模型实时返回',tool_call:'工具调用',tool_result:'工具结果',interaction:'交互事件'}[event.kind]||event.kind)
const percent=n=>n===undefined||n===null?'-':`${Math.round((Number(n)<=1?Number(n):Number(n)/100)*100)}%`
const score=n=>n===undefined||n===null?'—':`${Math.round(Number(n)<=1?Number(n)*100:Number(n))}`
const number=n=>n===undefined||n===null?'—':Number(n).toLocaleString()
const durationText=n=>n===undefined||n===null?'—':Number(n)>=1000?`${(Number(n)/1000).toFixed(1)} 秒`:`${Math.round(Number(n))} ms`
const statusText=s=>({completed:'已完成',partial_failed:'部分失败',running:'运行中',queued:'排队中',cancelling:'正在取消',failed:'失败',cancelled:'已取消',interrupted:'已中断'}[s]||s)
const statusType=s=>s==='failed'?'danger':s==='completed'||!s?'success':'warning'
const caseType=s=>String(s).toUpperCase()==='PASS'?'success':String(s).toUpperCase()==='ERROR'?'danger':'warning'
const caseStatus=s=>({PASS:'通过',FAIL:'未通过',ERROR:'执行错误'}[String(s).toUpperCase()]||s||'未知')
const caseScore=item=>item.grading?.summary?.pass_rate??(String(item.status).toUpperCase()==='PASS'?'100%':'0%')
const gradingText=g=>g?`判定：${caseStatus(g.status)}；执行 ${g.turns_executed??'—'} / ${g.turns_total??'—'} 轮；通过率 ${percent(g.summary?.pass_rate)}`:'未生成评分证据'
const questionScore=row=>`${Number(row.score??(row.passed?1:0)).toFixed(2)} / 1.00`
const readable=value=>value===undefined||value===null||value===''?'—':typeof value==='string'?value:Array.isArray(value)?value.map(readable).join('；'):Object.entries(value).map(([k,v])=>`${k}：${readable(v)}`).join('；')
const pretty=value=>JSON.stringify(value??{},null,2)
const objectValue=value=>{if(typeof value==='string'){try{return JSON.parse(value)}catch{return value}}return value}
const requestMessages=item=>{const raw=objectValue(item.proxy_server_request)||{};const request=objectValue(raw.body)||raw;const messages=objectValue(request.messages||item.messages||request.input);return Array.isArray(messages)?messages.map(m=>typeof m==='string'?{role:'user',content:m}:m):typeof messages==='string'?[{role:'user',content:messages}]:[]}
const responseMessages=item=>{const response=objectValue(item.response)||{};if(Array.isArray(response.choices))return response.choices.map(choice=>choice.message||choice.delta).filter(Boolean);if(Array.isArray(response.output))return response.output.map(x=>({role:x.role||'assistant',content:x.content||x.summary||x,tool_calls:x.type==='function_call'?[x]:[]}));return response.content?[{role:'assistant',content:response.content}]:[]}
const contentText=value=>{if(value==null||value==='')return'（无文本内容）';if(typeof value==='string')return value;if(Array.isArray(value))return value.map(part=>typeof part==='string'?part:(part.text||part.content||part.type||readable(part))).join('\n');return readable(value)}
const roleLabel=role=>({user:'用户',assistant:'模型',system:'系统',developer:'系统',tool:'工具'}[role]||role||'消息')
const systemPromptMessages=item=>requestMessages(item).filter(message=>['system','developer'].includes(String(message.role).toLowerCase()))
const currentUserMessages=item=>{const messages=requestMessages(item);const index=messages.map(message=>String(message.role).toLowerCase()).lastIndexOf('user');return index<0?[]:[messages[index]]}
const historyMessages=item=>{const messages=requestMessages(item);const currentUserIndex=messages.map(message=>String(message.role).toLowerCase()).lastIndexOf('user');return messages.filter((message,index)=>!['system','developer'].includes(String(message.role).toLowerCase())&&index!==currentUserIndex)}
const responseToolCalls=item=>responseMessages(item).flatMap(message=>(message.tool_calls||[]).map(tool=>({id:tool.id,name:tool.function?.name||tool.name||tool.type||'未知工具',arguments:tool.function?.arguments??tool.arguments??tool.input??{}})))
const interactionKey=(item,index)=>item.request_id||`interaction-${interactionPage.value}-${index}`
const isInteractionExpanded=(item,index)=>expandedInteractions.value.includes(interactionKey(item,index))
const actorLabel=item=>item.interaction_scope==='subagent'?`Subagent · ${item.subagent_name||'未命名'}`:'主 Agent'
const interactionStatus=status=>({success:'成功',failed:'失败',error:'错误'}[String(status||'').toLowerCase()]||status||'未知')
const interactionPreview=item=>{const prompt=currentUserMessages(item)[0];const output=responseMessages(item)[0];const text=contentText(prompt?.content||output?.content||'本轮没有可预览的文本内容').replace(/\s+/g,' ').trim();return text.length>150?`${text.slice(0,150)}…`:text}
const failureCategoryLabel=category=>({gateway_quota_exhausted:'模型使用额度已达上限',gateway_rate_limited:'模型服务请求过于频繁',gateway_server_error:'模型网关或上游服务异常',gateway_unavailable:'模型服务连接失败',gateway_authentication:'模型服务鉴权失败',gateway_authorization:'模型服务权限不足',model_incompatible:'指定模型不存在或不兼容',agent_workspace_invalid:'Agent 工作区配置无效',agent_execution_failed:'Agent 执行失败',model_verification_failed:'精确模型核验失败',trace_key_unavailable:'运行级轨迹 Key 创建失败'}[category]||category)
const failureTitle=(value,fallback='评测执行失败')=>value?.title||failureCategoryLabel(value?.category)||value?.summary||fallback
const failureShortDetail=(value,fallback='')=>value?.detail||fallback||'请进入详情页查看技术信息'
const failureDescription=(value,fallback='')=>{if(!value)return fallback;const parts=[value.detail||fallback,value.reset_after?`预计 ${value.reset_after} 后重置`:null,value.suggested_action?`建议：${value.suggested_action}`:null,value.technical_detail?`技术详情：${value.technical_detail}`:null].filter(Boolean);return parts.join(' ')}
const evidenceLabel=s=>({insufficient:'样本不足',exploratory:'探索性',adequate:'充分'}[s]||s||'—')
const qualityLabel=k=>({skill_md:'SKILL.md 完整性',name:'名称定义',description:'能力描述',workflow:'工作流程',constraints:'约束条件',output_contract:'输出契约',error_handling:'异常处理',verification:'验证方法'}[k]||k)
const qualityDescription=item=>({skill_md:'Skill 主说明文件存在且非空',name:'元数据中定义了明确名称',description:'元数据中描述了适用场景',workflow:'包含清晰的执行步骤',constraints:'明确说明边界与约束',output_contract:'定义输出或产物格式',error_handling:'说明失败与异常处理方式',verification:'说明如何验证执行结果'}[item.check]||item.description)
const formatTime=value=>value?new Date(value).toLocaleString():'时间未记录'
onMounted(()=>load());onBeforeUnmount(()=>clearTimeout(refreshTimer))
</script>

