.interaction-controls{display:grid;grid-template-columns:auto minmax(180px,260px) minmax(280px,1fr);align-items:center;gap:12px;margin-bottom:16px}.interaction-controls>.el-input:last-child{grid-column:-2/-1}.interaction-summary{grid-template-columns:repeat(4,minmax(0,1fr))}.subagent-overview{margin:0 0 18px;padding:14px;border:1px solid #ead9b7;border-radius:10px;background:#fffbf1}.subagent-overview-title{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:10px}.subagent-overview-title span{color:var(--muted);font-size:12px}.subagent-list{display:flex;gap:8px;overflow-x:auto;padding-bottom:2px}.subagent-list button{display:flex;flex:0 0 auto;flex-direction:column;align-items:flex-start;gap:4px;min-width:180px;padding:10px 12px;border:1px solid #dfcda8;border-radius:8px;background:var(--surface);color:var(--text);cursor:pointer;text-align:left;transition:.16s}.subagent-list button:hover,.subagent-list button.active{border-color:#c08b2f;background:#fff4d7}.subagent-list button span{color:var(--muted);font-size:12px}.interaction-log-list{border-top:1px solid var(--line)}.interaction-log-list :deep(.el-collapse-item__header){height:auto;min-height:82px;padding:0 12px;background:transparent}.interaction-log-list :deep(.el-collapse-item__content){padding:0 12px 18px}.interaction-log-row{display:grid;grid-template-columns:34px minmax(0,1fr) auto;align-items:center;gap:12px;width:100%;padding:12px 8px 12px 0}.turn-index{display:grid;place-items:center;width:30px;height:30px;border-radius:8px;background:var(--brand-soft);color:var(--brand);font-weight:700}.interaction-log-main{min-width:0}.interaction-log-main>div{display:flex;align-items:center;gap:7px}.interaction-log-main p{margin:5px 0 0;overflow:hidden;color:var(--muted);font-size:13px;line-height:1.45;text-overflow:ellipsis;white-space:nowrap}.interaction-log-meta{display:flex;flex-direction:column;align-items:flex-end;gap:5px;color:var(--muted);font-size:12px}.interaction-detail{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:14px;border:1px solid var(--line);border-radius:10px;background:var(--surface-2)}.interaction-detail-meta{display:flex;grid-column:1/-1;gap:18px;flex-wrap:wrap;padding-bottom:4px;color:var(--muted);font-size:12px}.message-section{min-width:0;overflow:hidden;border:1px solid var(--line);border-radius:9px;background:var(--surface)}.message-section>header{display:flex;align-items:center;justify-content:space-between;padding:10px 13px;border-bottom:1px solid var(--line)}.message-section>header span{color:var(--muted);font-size:12px}.message-section.user-prompt>header{border-left:4px solid #4b8ee8}.message-section.system-prompt>header{border-left:4px solid #8c69d8}.message-section.model-output>header{border-left:4px solid #25a66a}.message-section.history>header{border-left:4px solid #7c8792}.message-section.tools{grid-column:1/-1}.message-section.tools>header{border-left:4px solid #d59b2b}.message-stack{display:grid;gap:1px;max-height:520px;overflow:auto}.message-stack article{padding:12px 14px;border-bottom:1px solid var(--line)}.message-stack article:last-child{border-bottom:0}.message-stack strong{display:block;margin-bottom:6px;color:var(--muted);font-size:12px}.message-stack pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;color:var(--text);font:13px/1.6 ui-monospace,SFMono-Regular,Consolas,monospace}.raw-interaction{grid-column:1/-1;padding:11px 13px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}.raw-interaction summary{cursor:pointer;color:var(--brand);font-size:13px}.raw-interaction .interaction-body{margin-top:12px}.interaction-pagination{justify-content:flex-end;margin-top:18px}
